function text = output_description(route, folder, stem)
%OUTPUT_DESCRIPTION One-line meaning of a figure or table, from its family.
%   TEXT = study.output_description(ROUTE, FOLDER, STEM) returns what the
%   figure or table STEM (file name without extension) of the analysis
%   ROUTE/FOLDER shows, from the description of its family (the first file-name
%   pattern that matches). FOLDER 'case/<step>' describes an output of a case
%   folder, cases/case_<CaseID>/<step>/. '' when no family description exists;
%   the index of the analysis README then shows the title only.
%   Side effects: none.

    stem = char(string(stem));
    D = families();
    D = D(strcmp(D(:, 1), [char(route) '/' char(folder)]) | strcmp(D(:, 1), '*'), :);
    text = '';
    for i = 1:size(D, 1)
        if ~isempty(regexp(stem, ['^' D{i, 2} '$'], 'once'))
            text = D{i, 3};
            return;
        end
    end
end

